// Generates the social-share image (1200×630) for /malta/30-places-2026: a photo
// collage of six places beside the title. JPG on purpose: not every link preview
// (WhatsApp, Instagram DMs) renders WebP og:images.
// Run once, or after changing the picks: `node scripts/gen-og-top-places.js`.
const path = require('path');
const sharp = require('sharp');

const ACCENT = '#F4A922';
const CHARCOAL = '#15171c';
const assets = path.join(__dirname, '..', 'src', 'assets');
const OUT = path.join(assets, 'og-30-places-2026.jpg');

// Card crops (generated by convert-to-webp.js), chosen for colour and variety.
const PICKS = [
  'images/places/fomm-card.webp',
  'images/places/ta-maria-cave/TaMarijaCave-card.webp',
  'images/places/mini-inlandsea/mini-inlandsea-2-card.webp',
  'images/places/l-ghar-ta-santa-katarina/l-ghar-ta-santa-katarina-card.webp',
  'images/places/wied-il-ghasri-card.webp',
  'images/places/rock-card.webp',
];

const W = 1200, H = 630;
const COLS = 3, TILE_W = 252, TILE_H = 315; // 4:5, two rows fill the height
const GRID_X = W - COLS * TILE_W;

const text = `<svg width="${GRID_X}" height="${H}" xmlns="http://www.w3.org/2000/svg">
  <rect width="${GRID_X}" height="${H}" fill="${CHARCOAL}"/>
  <rect x="56" y="96" width="64" height="8" rx="4" fill="${ACCENT}"/>
  <g font-family="Helvetica, Arial, sans-serif" fill="#ffffff">
    <text x="56" y="160" font-size="26" font-weight="700" fill="${ACCENT}" letter-spacing="4">2026 EDITION</text>
    <text x="52" y="270" font-size="80" font-weight="900" letter-spacing="-2">30 places</text>
    <text x="54" y="340" font-size="58" font-weight="800" letter-spacing="-2">to visit in</text>
    <text x="54" y="410" font-size="58" font-weight="800" letter-spacing="-2">Malta</text>
    <text x="56" y="540" font-size="26" font-weight="600" fill="#cfc8bb">Filmed and mapped by</text>
    <text x="56" y="574" font-size="26" font-weight="700">@johnfabiomb</text>
  </g>
</svg>`;

(async () => {
  const tiles = await Promise.all(PICKS.map(async (file, i) => ({
    input: await sharp(path.join(assets, file)).resize(TILE_W, TILE_H, { fit: 'cover' }).toBuffer(),
    left: GRID_X + (i % COLS) * TILE_W,
    top: Math.floor(i / COLS) * TILE_H,
  })));

  await sharp({ create: { width: W, height: H, channels: 3, background: CHARCOAL } })
    .composite([{ input: Buffer.from(text), left: 0, top: 0 }, ...tiles])
    .jpeg({ quality: 84, mozjpeg: true })
    .toFile(OUT);

  console.log(`Wrote ${path.relative(process.cwd(), OUT)}`);
})().catch(err => { console.error(err); process.exit(1); });
